const r = await tools.ask_user_question({
  questions: [
    {
      id: "repo-visibility",
      header: "仓库可见性",
      question: "记忆数据进 git = 你和 AI 的全部对话内容、偏好上传到 GitHub。My-second-brain 仓库是私有的吗？（若公开，任何人都能读到你的完整历史）",
      options: [
        { label: "私有，放心推 (Recommended)", description: "只有你能看到，记忆数据进 git 无泄露风险" },
        { label: "公开/不确定", description: "先帮你确认可见性，公开的话先转私有再推" }
      ]
    },
    {
      id: "data-scope",
      header: "数据范围",
      question: "「所有的」具体拷哪些？灵枢（记忆+性格）、OpenViking（1406 个事件文件）、grill-first 偏好肯定进；DSH 原生会话记录（30+ 会话，体积最大，含完整对话原文）也进吗？",
      options: [
        { label: "三个记忆目录就够 (Recommended)", description: "灵枢+OpenViking+偏好，AI 记忆完整恢复；会话记录不进（体积大、含敏感原文，且灵枢已提炼过）" },
        { label: "全部进，包括会话记录", description: "连 DSH sessions/storages 一起推，新机连历史会话列表都能恢复" }
      ]
    },
    {
      id: "sync-mode",
      header: "同步机制",
      question: "一次性推完就结束，还是长期保持同步（每次会话有新记忆就随库推送）？",
      options: [
        { label: "长期同步 (Recommended)", description: "把「记忆数据随库推送」写进 AGENTS.md 规则，以后每次自动带上，新机随时拉到最新" },
        { label: "就这次推一次", description: "只推当前这一版，以后手动再说" }
      ]
    }
  ]
});
return r;
